"use client";

import { useState, useEffect, useRef } from "react";
import { getPlaceholderImage } from "@/lib/image-utils";
import { Package } from "lucide-react";
import { useProductStore } from "@/store/product-store";

interface SafeImageProps {
  src: string | null | undefined;
  alt: string;
  fill?: boolean;
  width?: number;
  height?: number;
  className?: string;
  priority?: boolean;
  loading?: "lazy" | "eager";
  sizes?: string;
  onError?: () => void;
  placeholder?: "blur" | "empty";
  blurDataURL?: string;
  productId?: string;
}

/**
 * کامپوننت SafeImage با تضمین لود شدن تصاویر
 * تصاویر را به blob و سپس data URL تبدیل می‌کند برای اطمینان از لود شدن
 */
export function SafeImage({
  src,
  alt,
  fill = false,
  width,
  height,
  className = "",
  priority = false,
  loading = "eager",
  sizes,
  onError,
  placeholder = "empty",
  blurDataURL,
  productId,
}: SafeImageProps) {
  const getProduct = useProductStore((state) => state.getProduct);
  const placeholderUrl = getPlaceholderImage(width || 600, height || 600);
  
  const [imageSrc, setImageSrc] = useState<string>(placeholderUrl);
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const imgRef = useRef<HTMLImageElement>(null);
  const cacheRef = useRef<Map<string, string>>(new Map());
  const abortControllerRef = useRef<AbortController | null>(null);

  // دریافت URL تصویر از multiple sources
  const getImageUrl = (): string | null => {
    // 1. از src prop
    if (src && typeof src === 'string' && src.trim() !== '') {
      return src.trim();
    }
    
    // 2. از product store
    if (productId) {
      const product = getProduct(productId);
      if (product?.images && Array.isArray(product.images) && product.images.length > 0) {
        for (const img of product.images) {
          if (img && typeof img === 'string' && img.trim() !== '') {
            return img.trim();
          }
        }
      }
    }
    
    return null;
  };

  // تبدیل تصویر به data URL برای تضمین لود شدن
  const convertToDataUrl = async (imageUrl: string): Promise<string | null> => {
    // اگر قبلاً cache شده، از cache استفاده کن
    if (cacheRef.current.has(imageUrl)) {
      return cacheRef.current.get(imageUrl) || null;
    }

    // اگر data URL یا blob URL است، مستقیماً برگردان
    if (imageUrl.startsWith('data:') || imageUrl.startsWith('blob:')) {
      cacheRef.current.set(imageUrl, imageUrl);
      return imageUrl;
    }

    try {
      // ایجاد AbortController برای timeout
      const controller = new AbortController();
      abortControllerRef.current = controller;
      
      const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 ثانیه timeout

      // Fetch تصویر
      // برای relative URLs، از window.location.origin استفاده کن
      let fetchUrl = imageUrl;
      if (!imageUrl.startsWith('http://') && !imageUrl.startsWith('https://') && !imageUrl.startsWith('data:') && !imageUrl.startsWith('blob:')) {
        if (imageUrl.startsWith('/')) {
          fetchUrl = `${window.location.origin}${imageUrl}`;
        } else {
          fetchUrl = `${window.location.origin}/${imageUrl}`;
        }
      }

      const response = await fetch(fetchUrl, {
        signal: controller.signal,
        cache: 'force-cache', // استفاده از cache برای سرعت بیشتر
        mode: 'cors', // برای CORS
        credentials: 'omit', // برای امنیت
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // تبدیل به blob
      const blob = await response.blob();
      
      // تبدیل blob به data URL
      return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          const dataUrl = reader.result as string;
          cacheRef.current.set(imageUrl, dataUrl);
          resolve(dataUrl);
        };
        reader.onerror = () => resolve(null);
        reader.readAsDataURL(blob);
      });
    } catch (error: any) {
      // اگر fetch ناموفق بود (مثلاً CORS)، از URL اصلی استفاده کن
      if (error.name !== 'AbortError') {
        // فقط در development log کن
        if (process.env.NODE_ENV === 'development') {
          console.warn('Failed to convert image to data URL, will use original URL:', imageUrl);
        }
      }
      return null;
    }
  };

  // Load تصویر با تضمین
  const loadImageWithGuarantee = async (imageUrl: string) => {
    setIsLoading(true);
    setHasError(false);

    // ابتدا تصویر را به data URL تبدیل کن
    const dataUrl = await convertToDataUrl(imageUrl);
    
    if (dataUrl) {
      // اگر تبدیل موفق بود، از data URL استفاده کن
      setImageSrc(dataUrl);
      setIsLoading(false);
      setHasError(false);
      return true;
    }

    // اگر تبدیل ناموفق بود، از URL اصلی استفاده کن
    // اما با preload
    return new Promise<boolean>((resolve) => {
      const img = new Image();
      
      img.onload = () => {
        setImageSrc(imageUrl);
        setIsLoading(false);
        setHasError(false);
        resolve(true);
      };
      
      img.onerror = () => {
        setIsLoading(false);
        setHasError(true);
        resolve(false);
      };
      
      img.src = imageUrl;
    });
  };

  // Initialize image source
  useEffect(() => {
    // Cleanup previous request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const imageUrl = getImageUrl();
    
    if (!imageUrl) {
      setImageSrc(placeholderUrl);
      setIsLoading(false);
      setHasError(false);
      return;
    }

    // Load تصویر با تضمین
    loadImageWithGuarantee(imageUrl).then((success) => {
      if (!success) {
        // اگر لود ناموفق بود، از product store fallback کن
        if (productId) {
          const product = getProduct(productId);
          if (product?.images && Array.isArray(product.images) && product.images.length > 0) {
            const fallbackImage = product.images.find(
              img => img && typeof img === 'string' && img.trim() !== '' && img !== imageUrl
            );
            if (fallbackImage) {
              loadImageWithGuarantee(fallbackImage.trim());
              return;
            }
          }
        }
        
        // در آخر placeholder
        setImageSrc(placeholderUrl);
        setIsLoading(false);
        setHasError(true);
        onError?.();
      }
    });

    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
  }, [src, productId, width, height, getProduct, placeholderUrl, onError]);

  const handleLoad = () => {
    setIsLoading(false);
    setHasError(false);
  };

  const handleError = () => {
    const imageUrl = getImageUrl();
    
    if (!imageUrl) {
      setIsLoading(false);
      setHasError(true);
      setImageSrc(placeholderUrl);
      onError?.();
      return;
    }

    // Retry با data URL conversion
    loadImageWithGuarantee(imageUrl).then((success) => {
      if (!success) {
        // از product store fallback کن
        if (productId) {
          const product = getProduct(productId);
          if (product?.images && Array.isArray(product.images) && product.images.length > 0) {
            const fallbackImage = product.images.find(
              img => img && typeof img === 'string' && img.trim() !== '' && img !== imageUrl
            );
            if (fallbackImage) {
              loadImageWithGuarantee(fallbackImage.trim());
              return;
            }
          }
        }
        
        setImageSrc(placeholderUrl);
        setIsLoading(false);
        setHasError(true);
        onError?.();
      }
    });
  };

  // مطمئن شو که imageSrc هرگز empty string نباشد
  const finalSrc = imageSrc || placeholderUrl;

  const imgProps: React.ImgHTMLAttributes<HTMLImageElement> = {
    src: finalSrc,
    alt,
    onLoad: handleLoad,
    onError: handleError,
    loading: loading,
    className: "object-cover w-full h-full",
    style: { objectFit: 'cover' },
    fetchPriority: priority ? 'high' : 'auto',
    decoding: 'async',
  };

  if (fill) {
    return (
      <div className={`relative ${className}`} style={{ width: '100%', height: '100%' }}>
        <img {...imgProps} ref={imgRef} />
        {isLoading && !hasError && (
          <div className="absolute inset-0 bg-muted animate-pulse flex items-center justify-center z-10">
            <Package className="h-8 w-8 text-muted-foreground" />
          </div>
        )}
      </div>
    );
  }
  
  return (
    <div className={`relative ${className}`} style={{ width, height }}>
      <img {...imgProps} ref={imgRef} />
      {isLoading && !hasError && (
        <div className="absolute inset-0 bg-muted animate-pulse flex items-center justify-center z-10">
          <Package className="h-8 w-8 text-muted-foreground" />
        </div>
      )}
    </div>
  );
}
